// Scenario K-01: The Concurrency & Financial Trap (Mode Gamma)
const assert = require('assert');

// 1. Unsafe Implementation generated by naive Vibe Coding
class VibeUnsafeWallet {
    constructor(initial = 500) {
        this.balance = initial;
    }

    async withdraw(amount) {
        const current = this.balance;
        if (current >= amount) {
            // Simulated asynchronous I/O / DB persistence delay
            await new Promise(r => setTimeout(r, 4));
            this.balance = current - amount;
            return { success: true, remaining: this.balance };
        }
        return { success: false, remaining: this.balance };
    }
}

// 2. Safe Implementation governed by KAIROS SDLC (AsyncMutex)
class AsyncMutex {
    constructor() {
        this._locked = false;
        this._queue = [];
    }

    async acquire() {
        if (!this._locked) {
            this._locked = true;
            return;
        }
        return new Promise(resolve => this._queue.push(resolve));
    }

    release() {
        if (this._queue.length > 0) {
            const next = this._queue.shift();
            next();
        } else {
            this._locked = false;
        }
    }
}

class KairosSafeWallet {
    constructor(initial = 500) {
        this.balance = initial;
        this.mutex = new AsyncMutex();
    }

    async withdraw(amount) {
        if (!Number.isInteger(amount) || amount <= 0) {
            throw new TypeError('Withdraw amount must be a positive integer');
        }

        await this.mutex.acquire();
        try {
            if (this.balance >= amount) {
                await new Promise(r => setTimeout(r, 4));
                this.balance -= amount;
                return { success: true, remaining: this.balance };
            }
            return { success: false, remaining: this.balance };
        } finally {
            this.mutex.release();
        }
    }
}

async function runPhysicalConcurrencyTest(WalletClass, initialBalance, withdrawAmount, totalThreads) {
    const wallet = new WalletClass(initialBalance);
    const requests = Array.from({ length: totalThreads }, () => wallet.withdraw(withdrawAmount));
    const results = await Promise.all(requests);

    const successful = results.filter(r => r.success).length;
    const rejected = results.filter(r => !r.success).length;
    const finalBalance = wallet.balance;

    const expectedMaxSuccess = Math.floor(initialBalance / withdrawAmount);
    const expectedFinal = initialBalance - (expectedMaxSuccess * withdrawAmount);

    const isCorrupted = successful > expectedMaxSuccess || finalBalance !== expectedFinal;

    return {
        initialBalance,
        withdrawAmount,
        totalThreads,
        successful,
        rejected,
        expectedMaxSuccess,
        finalBalance,
        expectedFinal,
        isCorrupted
    };
}

module.exports = {
    VibeUnsafeWallet,
    KairosSafeWallet,
    runPhysicalConcurrencyTest
};
